import{_ as a,o,c as t,a0 as r}from"./chunks/framework.tVbs9ddD.js";const h=JSON.parse('{"title":"Explanation: architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),s={name:"explanation/architecture.md"};function d(n,e,i,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="explanation-architecture" tabindex="-1">Explanation: architecture <a class="header-anchor" href="#explanation-architecture" aria-label="Permalink to &quot;Explanation: architecture&quot;">​</a></h1><p>kuda answers one question — <em>&quot;what does this project look like, right now, in a form an agent can load?&quot;</em> — and treats a wrong answer as worse than none.</p><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>repos ──► extract ──► summarize ──► index ──► store ──► serve</span></span>
<span class="line"><span>          │             │            │         │         │</span></span>
<span class="line"><span>   adapters:        adapters:    graph +   sqlite    cli |</span></span>
<span class="line"><span>   manifest         template     cards    + yaml    mcp | acp</span></span>
<span class="line"><span>   treesitter       (llm planned)  provenance</span></span>
<span class="line"><span>   lsp</span></span></code></pre></div><p><strong>Extract</strong> is mechanical — no model, fully rerunnable. It pulls symbols, package structure, and import edges.</p><p><strong>Summarize</strong> turns each module&#39;s extraction into an L1 card — committed YAML humans review in diffs.</p><p><strong>Index</strong> merges everything into the symbol/dependency graph with per-node provenance.</p><p><strong>Serve</strong> is read-side only: <code>find</code>, <code>dependents</code>, <code>refs</code>, <code>card</code>, <code>map</code>, <code>status</code> — plus the MCP and ACP wire surfaces.</p><h2 id="the-tiers-of-memory" tabindex="-1">The tiers of memory <a class="header-anchor" href="#the-tiers-of-memory" aria-label="Permalink to &quot;The tiers of memory&quot;">​</a></h2><ul><li><strong>L0 repo card</strong> (<code>.kuda/index.yaml</code>) — the ~1k-token always-load blob: purpose, module map, commands, provenance.</li><li><strong>L1 module cards</strong> (<code>.kuda/modules/*.yaml</code>) — fetched on demand when planning touches a module.</li><li><strong>L1.5 file cards</strong> (<code>.kuda/files/&lt;module&gt;/*.yaml</code>) — per-source-file <code>purpose</code> written by the semantic tier (opt-in, <code>[summarize] file_cards = true</code>). Files are chunked with a code-aware splitter (tree-sitter boundaries via text-splitter), fed to the agent, and hash-gated per file.</li><li><strong>L2 graph</strong> (<code>.kuda/index.sqlite</code>) — symbols, edges both directions, per-file hashes; gitignored, rebuildable, the query substrate.</li><li><strong>L3</strong> — the source itself. Memory is an index <em>into</em> code, never a replacement.</li></ul><p>Committed L0/L1/L1.5 + ignored L2 is deliberate: cards are reviewed prose, the graph is derived state.</p><h2 id="incremental-sync" tabindex="-1">Incremental sync <a class="header-anchor" href="#incremental-sync" aria-label="Permalink to &quot;Incremental sync&quot;">​</a></h2><p><code>sync</code> is diff-driven end to end:</p><ol><li>One walk groups manifests + source files by module (manifest package names, not dir names — <code>kuda-docs</code>, not <code>docs</code>).</li><li>Every file gets an in-process git blob hash — no subprocess per file.</li><li>Hashes are compared against the store&#39;s <code>files</code> table — unchanged modules are never re-parsed; a changed file re-parses only its own module.</li><li>Cards whose provenance matches are reused verbatim — the summarizer (and the agent, in <code>acp</code> mode) is only invoked for drift.</li></ol><p>Steady-state on a warm index is sub-second; agent spend is per-drift, never per-sync. Deleted files and vanished modules are detected by the same diff — their cards and store rows are removed.</p><h2 id="extraction-tiers" tabindex="-1">Extraction tiers <a class="header-anchor" href="#extraction-tiers" aria-label="Permalink to &quot;Extraction tiers&quot;">​</a></h2><p>Best-available wins, configured per repo via <code>[extract].kinds</code>:</p><ul><li><code>manifest</code> — free, no parser: package graph + module boundaries from Cargo.toml/package.json/pyproject/go.mod.</li><li><code>treesitter</code> — grammar+query data from <code>data/langs/*</code>: symbols and <code>use</code>/import edges in ~any language.</li><li><code>lsp</code> — <code>documentSymbol</code> against a real server (<code>lsp_server = &quot;rust-analyzer&quot;</code>); the strongest signal where a server exists. Absent server = silent skip.</li></ul><p>See <a href="./../how-to/languages.html">adding a language</a> — knowledge lives in descriptor files; adding one is a data change.</p><h2 id="language-as-data" tabindex="-1">Language as data <a class="header-anchor" href="#language-as-data" aria-label="Permalink to &quot;Language as data&quot;">​</a></h2><p>Per-language knowledge — grammar refs, symbol queries, manifest names — lives in <code>data/langs/*</code>, not in extractor code. The adapters&#39; vocabulary (<code>language()</code> registries, <code>SymbolKind</code>, <code>EdgeKind</code>) is the only fixed part.</p><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p><code>kuda-core</code> holds domain types only (<code>Symbol</code>, <code>ModuleCard</code>, <code>Provenance</code>, <code>Claim</code>-free config). Every concern is a trait crate + adapter crates:</p><ul><li><code>kuda-extract</code> → <code>kuda-manifest</code>, <code>kuda-treesitter</code>, <code>kuda-lsp</code></li><li><code>kuda-store</code> → <code>kuda-store-sqlite</code></li><li><code>kuda-summarize</code> → <code>kuda-template</code>, (<code>kuda-llm</code> planned)</li><li><code>kuda-vcs</code> → <code>kuda-git</code>; <code>kuda-config</code> → <code>kuda-config-toml</code>; <code>kuda-secret</code> → <code>kuda-keyring</code>, <code>kuda-dotenv</code></li></ul><p>New capability = new adapter crate, not a core rewrite.</p><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to &quot;Trust model&quot;">​</a></h2><p>Every artifact carries <code>provenance {files, hashes, commit_sha, generator}</code> — <code>kuda status</code> re-hashes and reports drift per card. Cards end with <code>verify:</code> — the files an agent should open before acting on the card. Memory is a hypothesis that narrows the search space; the code remains the only truth. <code>mimus audit</code> independently re-verifies card provenance — memory with an external falsifier.</p>`,27)])])}const m=a(s,[["render",d]]);export{h as __pageData,m as default};
